def max_Product(arr):
    if not arr:
        return None

    # Find the two largest numbers
    max1 = float('-inf')
    max2 = float('-inf')

    for num in arr:
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

    # Find the two smallest numbers (to handle negative product cases)
    min1 = float('inf')
    min2 = float('inf')

    for num in arr:
        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    product1 = max1 * max2
    product2 = min1 * min2

    if product1 > product2:
        return (max1, max2)
    else:
        return (min1, min2)

def sequence(n):
