def find_first_occurrence(arr, num):
    left, right = 0, len(arr) - 1

    # Binary search to find any occurrence of num
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == num:
            right = mid - 1  # Try to find an earlier occurrence
        elif arr[mid] < num:
            left = mid + 1
        else:
            right = mid - 1

    # If no occurrence found, return -1 (though problem implies it exists)
    if left >= len(arr):
        return -1

    return left

