def max_subarray_product(arr):
    if not arr:
        return 0

    max_so_far = arr[0]
    max_ending_here = arr[0]

    for i in range(1, len(arr)):
        num = arr[i]

        # Calculate possible values for max_ending_here
        # Either extend the previous subarray or start a new one with current number
        if num < 0:
            max_ending_here = min(num, -max_ending_here)
        else:
            max_ending_here = max(num, max_ending_here + num)

        # Update global maximum
        max_so_far = max(max_so_far, max_ending_here)

    return max_so_far

