def count_binary_seq(n):
    # The sum of first n bits must equal the sum of last n bits.
    # Let k be the number of 1s in the first half (and thus also in the second half).
    # k can range from 0 to n.
    # For a fixed k, the number of ways to arrange k ones and (n-k) zeros in one half is C(n, k).
    # Since the two halves are independent, we multiply the combinations: C(n, k) * C(n, k).

    total_count = 0

    # Calculate binomial coefficient C(n, k)
    def nCr(n, r):
        if r < 0 or r > n:
            return 0
        if r == 0 or r == n:
            return 1
        if r > n // 2:
            r = n - r

        res = 1
        for i in range(r):
            res = res * (n - i) // (i + 1)
        return res

    for k in range(n + 1):
        ways_half = nCr(n, k)
        total_count += ways_half * ways_half

    return float(total_count)

