def get_ludic(n):
    def is_ludic(num):
        if num < 2:
            return True
        factors = []
        i = 2
        temp = num
        while i * i <= temp:
            while temp % i == 0:
                factors.append(i)
                temp //= i
            i += 1
        if temp > 1:
            factors.append(temp)

        for factor in factors:
            if not is_ludic(factor):
                return False
        return True

    result = []
    for i in range(2, n + 1):
        if is_ludic(i):
            result.append(i)
    return result

