def remove_Occ(s, char):
    start = s.find(char)
    end = s.rfind(char)

    if start == -1 or end == -1:
        return s

    if start == 0 and end == len(s) - 1:
        return s[1:-1]

    if start == 0:
        return s[1:end+1][:-1] + s[end+1:]

    if end == len(s) - 1:
        return s[:start] + s[start+1:]

    return s[:start] + s[start+1:end] + s[end+1:]

