def reverse_vowels(s):
    vowels = "aeiouAEIOU"
    result = list(s)
    left, right = 0, len(result) - 1

    while left < right:
        if result[left] not in vowels:
            left += 1
        elif result[right] not in vowels:
            right -= 1
        else:
            result[left], result[right] = result[right], result[left]
            left += 1
            right -= 1

    return "".join(result)

